UNIT='(((((((....))(((((((((...))))..((((...)))))))))((....)))))))..'
SUFFIX=')))))((....)))))))((((...))))'
TARGET=PREFIX+UNIT*5+SUFFIX
N=len(TARGET)

def build_pair():
    stack=[]; pair=[-1]*N
    for i,c in enumerate(TARGET):
        if c=='(': stack.append(i)
        elif c==')':
            j=stack.pop(); pair[i]=j; pair[j]=i
    return pair
PAIR=build_pair()
TPAIRS=set((i,PAIR[i]) for i in range(N) if PAIR[i]>=0 and i<PAIR[i])

COMP={'G':'C','C':'G','A':'U','U':'A'}

def init_seq(seed):
    random.seed(seed)
    s=[]
    for i in range(N):
        if PAIR[i]<0: s.append(random.choice('ACGU'))
        elif i<PAIR[i]: s.append(random.choice('GCAU'))
        else: s.append(COMP[s[PAIR[i]]])
    return ''.join(s)

def fold_pairs(ss):
    st=[]; fp=set()
    for i,c in enumerate(ss):
        if c=='(': st.append(i)
        elif c==')':
            j=st.pop(); fp.add((j,i))
    return fp

def score(s):
    fc=RNA.fold_compound(s); ss,_=fc.mfe()
    return RNA.bp_distance(ss,TARGET), ss

def one(restart):
    random.seed(restart)
    seq=init_seq(restart)
    s, dist = RNA.inverse_fold(seq, TARGET)
    fc=RNA.fold_compound(s); ss,_=fc.mfe()
    d=RNA.bp_distance(ss,TARGET)
    return (d, s, restart)

if __name__=='__main__':
    print('TARGET len',N, flush=True)
    Nrest=int(sys.argv[1]) if len(sys.argv)>1 else 100
    best=(9999,'',-1)
